#define main bridge_program_main
#include "bridge.c"
#include "ids.h"
#undef main
static int passes,failures;
static void check(bool x,const char*s){printf("%s %s\n",x?"PASS":"FAIL",s);if(x)passes++;else failures++;}
static int health(int p){party_context_activate(p);int n=0;for(int c=0;c<4;c++)n+=g_champions[c].current_health;return n;}
static int pending(int p){party_context_activate(p);int n=0;for(int c=0;c<4;c++)n+=g_champions[c].runtime.pending_damage;return n;}
static void setup(void){for(int p=0;p<2;p++){select_party(p);g_party_map_index=levelmap;g_party_map_x=p?9:8;g_party_map_y=1;g_party_direction=p?3:1;g_session.party_dead=false;g_party_connected[p]=true;for(int c=0;c<4;c++){g_champions[c].cell=c;g_champions[c].direction=g_party_direction;g_champions[c].current_health=g_champions[c].maximum_health;g_champions[c].current_stamina=g_champions[c].maximum_stamina;g_champions[c].runtime.pending_damage=0;g_champions[c].runtime.pending_wounds=0;}int d=g_party_direction;g_champions[d].cell=0;g_champions[0].cell=d;}select_party(0);map_set_current_map(levelmap);}
static bool hit(int p){select_party(p);for(int i=0;i<40;i++){action_is_action_performed(0,ACTION_SWING);int16_t d;if(action_recent_melee(&d)&&d>0)return true;}return false;}
int main(int argc,char**argv){if(argc<2||!init(argv[1]))return 2;connection(0,true);connection(1,true);
for(int shooter=0;shooter<2;shooter++){setup();int target=1-shooter,hp=health(target);select_party(shooter);int stamina=g_champions[0].current_stamina;bool landed=hit(shooter);check(landed,shooter?"B sword hits party A":"A sword hits party B");check(g_active_party==shooter&&g_event_owner==shooter,"melee restores attacker context and owner");check(g_champions[0].current_stamina<stamina,"original melee stamina cost debited to attacker");int queued=pending(target);check(queued>0,"armour-resolved damage queued on target");check(health(target)==hp,"melee respects original end-of-tick damage timing");select_party(target);champion_apply_pending_damage();check(health(target)==hp-queued,"native applied damage equals advertised queued amount");select_party(target);bool splat=false;for(int c=0;c<4;c++)if(g_champions[c].runtime.recent_damage>0)splat=true;check(splat,"victim per-champion incoming damage record");}
setup();select_party(0);g_champions[0].cell=3;g_champions[3].cell=1;int hp=health(1);select_party(0);action_is_action_performed(0,ACTION_SWING);int16_t result=0;check(action_recent_melee(&result)&&result==ACTION_DAMAGE_CANT_REACH,"blocked back-row sword reports original CANT REACH");check(pending(1)==0&&health(1)==hp,"blocked back row causes zero damage");select_party(0);const char*error=control_run_action("swap_champions","{\"a\":0,\"b\":3}");check(!error&&g_champions[0].cell==1,"original grid swap moves swordsman into front row");check(hit(0),"same swordsman can hit after original grid reposition");
setup();connection(1,false);select_party(0);action_is_action_performed(0,ACTION_SWING);check(pending(1)==0,"withdrawn party cannot receive melee damage");
setup();select_party(1);g_party_map_x=10;select_party(0);action_is_action_performed(0,ACTION_SWING);check(pending(1)==0,"two-tile distance cannot be reached by melee");
setup();select_party(1);g_party_map_index=0;select_party(0);action_is_action_performed(0,ACTION_SWING);check(pending(1)==0,"party on another map cannot be struck");
setup();select_party(1);for(int c=0;c<4;c++)g_champions[c].current_health=0;g_session.party_dead=true;select_party(0);action_is_action_performed(0,ACTION_SWING);check(pending(1)==0,"dead party cannot be struck");
setup();select_party(0);g_party_map_x=23;g_party_map_y=2;g_party_direction=2;g_champions[0].direction=2;g_champions[0].cell=2;g_champions[2].cell=1;select_party(1);g_party_map_x=23;g_party_map_y=3;select_party(0);action_is_action_performed(0,ACTION_SWING);check(pending(1)==0,"closed original level door blocks party melee");
printf("SUMMARY %d passed %d failed\n",passes,failures);return failures?1:0;}
